const it = $input.item.json;
const fmt = (it.display_format || '').toLowerCase();
const mt = (it.media_type || '').toLowerCase();
const lane = fmt === 'dco' ? ('dco/' + mt) : (fmt + '/' + mt);
const isVideo = mt === 'video';
const ext = isVideo ? 'mp4' : 'jpg';
const contentType = isVideo ? 'video/mp4' : 'image/jpeg';
const slug = (it.brand_name || 'unknown').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const assetPath = slug + '/' + it.id + '.' + ext;
const thumbForClassify = it.thumbnail_url || it.media_url || 'https://placehold.co/1x1/png';
const mainUrl = it.media_url || it.thumbnail_url || 'https://placehold.co/1x1/png';
return { json: { ...it, _lane: lane, _ext: ext, _contentType: contentType, _assetPath: assetPath, _slug: slug, _thumbForClassify: thumbForClassify, _mainUrl: mainUrl } };
